//! End-to-end tests for `lege-pdf-audit inspect`, against PDFs generated by
//! `pdf-test-support` so no fixture files are checked in.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    reason = "a failed unwrap is a failed test"
)]

use std::path::PathBuf;
use std::process::Command;

fn bin() -> Command {
    Command::new(env!("CARGO_BIN_EXE_lege-pdf-audit"))
}

/// A scratch path unique to this test process and name.
fn work_file(name: &str) -> PathBuf {
    std::env::temp_dir().join(format!("lege-pdf-audit-{}-{name}", std::process::id()))
}

fn write_fixture(name: &str, bytes: &[u8]) -> PathBuf {
    let path = work_file(name);
    std::fs::write(&path, bytes).unwrap();
    path
}

fn remove(path: &PathBuf) {
    let _ = std::fs::remove_file(path);
}

#[test]
fn inspect_prints_a_terminal_report() {
    let pdf = write_fixture(
        "terminal.pdf",
        &pdf_test_support::builder::multipage_classic(2),
    );
    let output = bin().arg("inspect").arg(&pdf).output().unwrap();
    remove(&pdf);
    assert!(
        output.status.success(),
        "stderr={}",
        String::from_utf8_lossy(&output.stderr)
    );

    let stdout = String::from_utf8_lossy(&output.stdout);
    // Disposition first: while the M1 inventory is partial, the only honest
    // verdict is inconclusive.
    for needle in [
        "PDF INTEGRITY REPORT",
        "Result: INCONCLUSIVE",
        "SHA-256:",
        "Size:",
        "Pages: 2",
        "Parse: clean",
        "Xref sections:",
        "Revisions: 1 revision",
        "Analysis: full",
        "Findings (0)",
        "Pending sections",
        "signature_cryptography",
        "Absence of findings does not prove authenticity",
    ] {
        assert!(stdout.contains(needle), "missing {needle:?} in:\n{stdout}");
    }
}

#[test]
fn json_flag_writes_a_versioned_report_file() {
    let bytes = pdf_test_support::builder::multipage_classic(1);
    let pdf = write_fixture("json-file.pdf", &bytes);
    let json_path = work_file("json-file.audit.json");
    let output = bin()
        .arg("inspect")
        .arg(&pdf)
        .arg("--json")
        .arg(&json_path)
        .output()
        .unwrap();
    remove(&pdf);
    assert!(
        output.status.success(),
        "stderr={}",
        String::from_utf8_lossy(&output.stderr)
    );
    // The terminal report still goes to stdout alongside the JSON file.
    assert!(String::from_utf8_lossy(&output.stdout).contains("PDF INTEGRITY REPORT"));

    let text = std::fs::read_to_string(&json_path).unwrap();
    remove(&json_path);
    let value: serde_json::Value = serde_json::from_str(&text).unwrap();
    assert_eq!(value["schema_version"], 1);
    assert_eq!(value["disposition"], "INCONCLUSIVE");
    assert_eq!(
        value["document"]["identity"]["size_bytes"],
        bytes.len() as u64
    );
    assert_eq!(value["document"]["pages"]["status"], "available");
}

#[test]
fn json_dash_writes_only_json_to_stdout() {
    let pdf = write_fixture(
        "json-stdout.pdf",
        &pdf_test_support::builder::multipage_classic(1),
    );
    let output = bin()
        .arg("inspect")
        .arg(&pdf)
        .arg("--json=-")
        .output()
        .unwrap();
    remove(&pdf);
    assert!(
        output.status.success(),
        "stderr={}",
        String::from_utf8_lossy(&output.stderr)
    );

    // The whole of stdout must parse: the terminal report is suppressed.
    let stdout = String::from_utf8_lossy(&output.stdout);
    let value: serde_json::Value = serde_json::from_str(&stdout).unwrap();
    assert_eq!(value["schema_version"], 1);
}

#[test]
fn password_flag_is_accepted_and_structure_only_is_labelled() {
    let pdf = write_fixture(
        "aes256.pdf",
        &pdf_test_support::builder::aes256_encrypted_fixture(),
    );
    let output = bin()
        .arg("inspect")
        .arg(&pdf)
        .arg("--password")
        .arg("wrong")
        .output()
        .unwrap();
    remove(&pdf);
    // A declined password still produces a report: a structure-only audit.
    assert!(
        output.status.success(),
        "stderr={}",
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("Analysis: structure-only"), "in:\n{stdout}");
    assert!(
        stdout.contains("Pages: unavailable (encrypted"),
        "in:\n{stdout}"
    );
}

#[test]
fn missing_input_fails_with_a_stderr_message() {
    let output = bin()
        .arg("inspect")
        .arg(work_file("does-not-exist.pdf"))
        .output()
        .unwrap();
    assert!(!output.status.success());
    assert!(!String::from_utf8_lossy(&output.stderr).is_empty());
}

#[test]
fn unwritable_json_path_fails_with_a_stderr_message() {
    let pdf = write_fixture(
        "unwritable-json.pdf",
        &pdf_test_support::builder::multipage_classic(1),
    );
    let output = bin()
        .arg("inspect")
        .arg(&pdf)
        .arg("--json")
        .arg(work_file("no-such-dir/report.json"))
        .output()
        .unwrap();
    remove(&pdf);
    assert!(!output.status.success());
    assert!(!String::from_utf8_lossy(&output.stderr).is_empty());
}

#[test]
fn inspect_lists_each_revision_and_finding() {
    let pdf = write_fixture("revisions.pdf", &pdf_test_support::builder::gpa_edit());
    let output = bin().arg("inspect").arg(&pdf).output().unwrap();
    remove(&pdf);
    assert!(
        output.status.success(),
        "stderr={}",
        String::from_utf8_lossy(&output.stderr)
    );

    let stdout = String::from_utf8_lossy(&output.stdout);
    for needle in [
        "Result: REVIEW RECOMMENDED",
        "Revisions: 2 revisions",
        "Revision 0:",
        "Revision 1:",
        "Findings (1)",
        "TEXT_CHANGED_BETWEEN_REVISIONS",
    ] {
        assert!(stdout.contains(needle), "missing {needle:?} in:\n{stdout}");
    }
}

#[test]
fn evidence_dir_writes_png_artifacts_and_lists_them() {
    let pdf = write_fixture("evidence.pdf", &pdf_test_support::builder::gpa_edit());
    let dir = work_file("evidence-gpa-dir");
    let output = bin()
        .arg("inspect")
        .arg(&pdf)
        .arg("--evidence-dir")
        .arg(&dir)
        .output()
        .unwrap();
    remove(&pdf);
    assert!(
        output.status.success(),
        "stderr={}",
        String::from_utf8_lossy(&output.stderr)
    );

    let stdout = String::from_utf8_lossy(&output.stdout);
    for needle in [
        "Evidence (3)",
        "rev00-to-rev01-page-000-before.png",
        "rev00-to-rev01-page-000-after.png",
        "rev00-to-rev01-page-000-diff.png",
    ] {
        assert!(stdout.contains(needle), "missing {needle:?} in:\n{stdout}");
    }
    for name in [
        "rev00-to-rev01-page-000-before.png",
        "rev00-to-rev01-page-000-after.png",
        "rev00-to-rev01-page-000-diff.png",
    ] {
        let bytes = std::fs::read(dir.join(name)).unwrap();
        assert!(
            bytes.starts_with(&[137, 80, 78, 71, 13, 10, 26, 10]),
            "{name} is a PNG"
        );
    }
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn usage_errors_exit_nonzero_with_help() {
    for args in [vec![], vec!["diff", "a.pdf"], vec!["inspect"]] {
        let output = bin().args(&args).output().unwrap();
        assert!(!output.status.success(), "{args:?} should fail");
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(stderr.contains("Usage:"), "{args:?} printed:\n{stderr}");
    }

    let output = bin().arg("--help").output().unwrap();
    assert!(output.status.success());
    assert!(
        String::from_utf8_lossy(&output.stdout).contains("Usage:"),
        "help should go to stdout"
    );
}
